fld=OxmlElement('w:fldSimple'); fld.set(qn('w:instr'),'PAGE'); footer._p.append(fld)

def p(t='',style=None): return d.add_paragraph(t,style)
def h(t,l=1): d.add_heading(t,l)
def bullets(items):
    for x in items:d.add_paragraph(x,style='List Bullet')
def table(headers,rows,widths=None):
    t=d.add_table(rows=1,cols=len(headers)); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.style='Table Grid'
    for i,x in enumerate(headers): t.rows[0].cells[i].text=str(x); shade(t.rows[0].cells[i],'163A5F'); color_runs(t.rows[0].cells[i],'FFFFFF',True)
    repeat(t.rows[0])
    for ri,row in enumerate(rows):
        cells=t.add_row().cells
        for i,x in enumerate(row): cells[i].text=str(x); cells[i].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
        if ri%2==1:
            for c in cells: shade(c,'F0F4F8')
    if widths:
        for row in t.rows:
            for i,w in enumerate(widths): row.cells[i].width=Inches(w)
    d.add_paragraph()
    return t
def shade(c,fill):
    pr=c._tc.get_or_add_tcPr(); el=OxmlElement('w:shd'); el.set(qn('w:fill'),fill); pr.append(el)
def color_runs(c,col,bold=False):
    for para in c.paragraphs:
        for r in para.runs:r.font.color.rgb=RGBColor.from_string(col); r.bold=bold
def repeat(row):
    trPr=row._tr.get_or_add_trPr(); el=OxmlElement('w:tblHeader'); el.set(qn('w:val'),'true'); trPr.append(el)
def code(txt):
    x=d.add_paragraph(); x.paragraph_format.left_indent=Inches(.2); r=x.add_run(txt); r.font.name='Consolas'; r.font.size=Pt(8)

# Cover and contents
d.add_paragraph('\n\n')
title=d.add_paragraph(style='Title'); title.alignment=WD_ALIGN_PARAGRAPH.CENTER; title.add_run('Public Transport Ridership Analysis')
sub=d.add_paragraph(); sub.alignment=WD_ALIGN_PARAGRAPH.CENTER; sub.add_run('Complete Project Report and User Manual').bold=True
d.add_paragraph('\n')
for line in ['Study area: Bareilly, Uttar Pradesh, India','Academic context: BCA-AI','Application: Python, Streamlit, Pandas, NumPy, Plotly and SQLite','Prepared: 31 October 2026']:
    q=d.add_paragraph(line); q.alignment=WD_ALIGN_PARAGRAPH.CENTER
d.add_page_break(); h('Contents',1)
for x in ['1. Introduction','2. System requirements and installation','3. Application walkthrough','4. Dataset reference','5. Observed data and simulation data','6. Practical workflows','7. Data import and management','8. Analytics and formulas','9. Database and architecture','10. Research sources','11. Troubleshooting','12. Evaluation and future scope','13. Glossary and operational checklist','14. Conclusion'] : p(x)
d.add_page_break()

h('1. Introduction')
p('This project is a local academic dashboard for organising and analysing public transport information related to Bareilly. It combines a persistent SQLite store for user-provided observed records with a separate, reproducible in-memory simulation mode. The system is useful for demonstrating analytical workflows while keeping the evidence status of every figure clear.')
h('1.1 Why public transport analysis matters',2); p('Ridership and service records can help transport planners understand when people travel, where demand is concentrated, whether scheduled service is delivered, and how vehicles are used. Reliable conclusions depend on consistent coverage, clear measurement units and trustworthy source records.')
h('1.2 Problem, objectives and scope',2); p('Public route-day ridership and current operational files for Bareilly were not verified in the project research. The application addresses this evidence gap by providing import templates, data checks and useful analysis when data exists, plus simulation for demonstrations. Its scope includes five data families: ridership, routes, stops, fleet and operations.')
bullets(['Organise available evidence without presenting proposals as active service.','Support documented CSV import, export, source notes and database backup.','Explore route and stop relationships and calculate operational indicators where fields support them.','Demonstrate charts and filters using a fixed-seed synthetic scenario.'])
h('1.3 Intended users and expected outcomes',2); p('The main users are the student developer, academic evaluators and readers who need to inspect transport records. Expected outcomes are a repeatable application workflow, transparent source limitations and a foundation for analysis when reliable local data becomes available.')
h('1.4 Management system and analytical dashboard',2); p('A data management system stores, validates, tracks and exports records. An analytical dashboard aggregates records into indicators and visual summaries. This project includes both functions: the Data Centre handles files and SQLite persistence, while Overview, Ridership, Network and Operations present analysis.')
h('1.5 Assumptions and limitations',2); p('Imported records are interpreted according to their supplied reporting unit. The application cannot establish citywide coverage unless the data source supports that claim. Research mode currently has zero ridership, fleet and operations records. The twenty documented stops do not have verified coordinates. Simulation values and simulated coordinates are illustrative only.')

h('2. System requirements and installation')
table(['Requirement','Recommended / actual'],[['Operating system','Windows 10 or 11'],['Python','Python 3.10 or newer; use the Python launcher `py`'],['Memory','4 GB minimum; 8 GB recommended'],['Storage','At least 500 MB for project, environment and data'],['Browser','Current Edge, Chrome or Firefox'],['Dependencies','See requirements.txt: Streamlit, Pandas, NumPy, Plotly, pytest']])
h('2.1 Project structure',2)
table(['Path','Purpose'],[['app.py','Streamlit pages, filters, charts and UI'],['transport_core.py','SQLite schema, CSV templates, validation, import, backup and recovery'],['simulation.py','Fixed-seed in-memory demonstration data generator'],['data/ridership.sqlite','Persistent observed data and import/source registers'],['data/templates/','CSV schemas for five observed datasets'],['data/reference/','CMP proposed-route reference file'],['data/uploads/','Archived accepted CSV uploads'],['data/backups/','Database and project safety backups'],['research/','Source register and evidence audit'],['docs/','Methodology and data dictionary']])
h('2.2 Install and launch',2)
code('cd D:\\Public-Transport-Ridership-Analysis\npy --version\npy -m venv .venv\n.venv\\Scripts\\python.exe -m pip install -r requirements.txt\n.venv\\Scripts\\python.exe -m streamlit run app.py')
p('The first command changes the terminal to the project folder. The version command confirms Python is available. `venv` creates an isolated environment for this project. The pip command installs only packages listed in requirements.txt. The final command starts Streamlit. Open http://localhost:8501 in a browser.')
p('To open the project in VS Code, choose File → Open Folder and select D:\\Public-Transport-Ridership-Analysis. Use Terminal → New Terminal, then run the commands above. Stop the server with Ctrl+C in its terminal. To restart it, run the Streamlit command again. If port 8501 is occupied, use `--server.port 8502` and open http://localhost:8502.')

h('3. Application walkthrough')
p('The sidebar contains a mode selector and the navigation names below. Research / Observed Data reads SQLite. Simulation / Demonstration Data generates the synthetic scenario at runtime and displays a warning banner.')
h('3.1 Overview',2); p('Shows passenger, trip, active-route, available-fleet, average-occupancy, on-time and revenue KPIs when ridership exists, plus a route filter and daily trend, route demand, time-period demand and weekday/weekend comparisons. Metrics use the selected mode. In observed mode with no ridership, it shows an empty-state message and ridership template download rather than passenger charts. Active routes exclude records labelled as proposed.')
h('3.2 Ridership',2); p('Select route IDs, a date range and daily, weekly or monthly trend. The page shows aggregated passenger counts, a moving average, route comparison, average passenger counts by time period, passenger distribution and highest/lowest bucket in the filtered data. A CSV export downloads the filtered rows. Observed mode currently shows the required columns and template because there are no observed ridership rows.')
h('3.3 Network',2); p('Filter route classification, compare route distances and linked stop counts, then select a route to inspect its details and ordered stop sequence. A map can appear when real coordinates exist. Simulation stops use illustrative coordinates and are labelled as such. Existing documented route references and proposed CMP routes are separate records; no observed stops are assigned to proposed routes.')
h('3.4 Operations',2); p('When operations exist, the page calculates trip count, on-time percentage (departure delay at most five minutes), mean departure delay and completed trips. It compares route reliability, plots daily trip counts, summarizes fleet size, availability and average capacity, and lists trips delayed over ten minutes or not marked completed. Fleet analysis is included on this page rather than a separate navigation item. Empty observed operations produce an explanatory message.')
h('3.5 Data Centre',2); p('In research mode, choose one of five datasets, download the matching template, upload a CSV and review up to twenty preview rows. Select Validate and import to run validation and append new records. The lower page provides a stored record explorer, CSV export, import history and a source metadata form. In simulation mode, imports are not shown; the page explains that demonstration data remains in memory.')
h('3.6 Data Quality',2); p('Shows row counts, missing cells, duplicate rows and date coverage. It identifies route and bus IDs without matching reference records and displays rejected import history in research mode. This is a diagnostic summary, not a full source-coverage audit.')
h('3.7 Sources & Planning',2); p('Displays the source catalogue, a separate existing-route reference section and the CMP Phase-1 proposed routes file. In simulation mode it notes the fixed seed and 90-day coverage. The page does not claim that the proposal file proves current service.')
h('3.8 System & Method',2); p('Shows SQLite integrity status, creates timestamped database backups, downloads the current database, and offers recovery after an uploaded database passes integrity_check and the user types RESTORE. Before replacing the live database, the current database is preserved as a backup. The page also summarizes evidence categories and methodological limitations.')

h('4. Dataset reference')
p('Observed CSV import schemas are defined in transport_core.py. The templates are intentionally header-only except the ridership example file; any example values must be treated as illustrative.')
datasets=[('Ridership','service_date (required, date); passengers (required, whole non-negative number); route_id, route_name (optional text); trips, revenue (optional numeric).','Row-hash duplicate handling. Used for passenger sums, route ranking, time-series and revenue where present.'),('Routes','route_id and route_name required; endpoints, distance, frequency, headway and route_type optional.','route_id is the primary identifier. Existing conflicts are ignored; not overwritten.'),('Stops','stop_id and stop_name required; coordinates, route_id and sequence optional.','stop_id identifies a stop. Coordinates are bounded to valid latitude/longitude ranges. Route linkage is checked after import.'),('Fleet','bus_id, capacity and status required; route_id and vehicle_type optional.','bus_id identifies a vehicle. Capacity is whole and non-negative. Route linkage is checked after import.'),('Operations','service_date, route_id, bus_id, scheduled_trips and actual_trips required; delay_minutes optional.','Actual trips cannot exceed scheduled trips. Date and trip count are validated; route and bus links are reported by Data Quality.')]
table(['Dataset','Fields and meaning','Rules and use'],datasets)
h('4.1 Synthetic row examples',2); p('The following values are fictional schema examples; do not present them as Bareilly observations.')
for x in ['Ridership: 2026-01-01, EXAMPLE-R1, Illustrative route, 120 passengers, 4 trips, ₹2,160 revenue.','Route: EXAMPLE-R1, Illustrative route, North terminal to South terminal, 12.5 km.','Stop: EXAMPLE-S1, Illustrative stop, route EXAMPLE-R1, sequence 1, coordinates illustrative.','Fleet: EXAMPLE-B1, route EXAMPLE-R1, midi bus, 35 seats, Available.','Operation: 2026-01-01, EXAMPLE-R1, EXAMPLE-B1, 4 scheduled trips, 4 actual, 3 minutes delay.']: p(x, 'List Bullet')
h('4.2 Keys and relationships',2); p('A primary key uniquely identifies a row, such as route_id, stop_id or bus_id. A foreign key is a field pointing to another table. Conceptually, route_id links ridership, stops, fleet and operations to routes; bus_id links operations to fleet. The current observed importer does not block unmatched route/bus references during import; Data Quality reports them afterward. Simulation has trip_id values, but observed CSV templates currently do not include trip_id.')

h('5. Observed data and simulation data')
h('5.1 Research / Observed Data',2); p('This mode reads the persistent SQLite tables. It can contain user-imported operational records, source metadata and documented route/stop references. Planning proposals and published aggregate values are evidence categories, not passenger trip records. The current database has five route records, twenty stop records, zero ridership rows, zero fleet rows and zero operations rows.')
h('5.2 Simulation / Demonstration Data',2); p('simulation.py uses NumPy random generator seed 20261031 to construct a 90-day scenario with four scenario routes, 32 illustrative stops, 24 buses, 1,080 ridership trip records and 1,080 operation trip records. Demand is shaped by route weights, weekday/weekend scaling and morning/off-peak/evening multipliers. Revenue is passengers multiplied by an illustrative ₹18 fare. Trip assignments use available simulated buses; delays and durations vary around scenario assumptions. All identifiers use SIM- prefixes and simulated stop coordinates carry “Illustrative only”.')
p('Simulation is generated in memory each run and never inserted into observed SQLite tables. Use it to demonstrate filters, charts and relationships, not to claim real city demand, capacity, service reliability or fares. The banner at the top identifies simulation mode.')

h('6. Practical workflows')
walks=[('Launch','Open project terminal; run `.venv\\Scripts\\python.exe -m streamlit run app.py`; visit localhost:8501. Expect sidebar and Overview.'),('Explore overview','Choose a mode. In simulation, read the warning then inspect KPIs and charts. In research, expect the no-ridership empty state.'),('Route demand','Choose Simulation mode → Overview or Ridership; filter route IDs. Compare passenger aggregates across routes in the generated scenario.'),('Peak periods','Open Ridership in simulation; compare Morning peak, Off-peak and Evening peak. These are scenario patterns.'),('Weekday/weekend','Overview has a grouped comparison based on each record’s service-date weekday.'),('Distance and stops','Network → select class filters → compare distance and linked stop bars → select a route to inspect its stop order.'),('Scheduled versus actual','Operations in simulation; compare reliability, delay and completed status. Research mode remains empty until operation records are imported.'),('Vehicle utilisation','Operations → vehicle trip assignments chart. The synthetic scenario has trip counts per bus; capacity-utilisation is generated per trip but the page does not present a dedicated capacity-utilisation chart.'),('Upload CSV','Research mode → Data Centre → choose dataset → download template → prepare file → upload → inspect preview → validate/import.'),('Correct invalid rows','Read the rejection message and Data Quality import history; fix column names, dates, numeric values, key duplicates or count constraints, then upload again.'),('Export filtered output','Ridership filter rows then choose its export button. Data Centre exports all stored rows for the chosen dataset.'),('Backup database','System & Method → Create database backup, or download current database. A timestamped copy is saved under data/backups.')]
table(['Task','Steps and expected result'],walks)

h('7. Data import and management')
for x in ['Choose Research / Observed Data.','Select the dataset in Data Centre and download the matching template.','Preserve exact header spelling. Dates should be recognizable by Pandas; numeric fields must contain numbers.','Upload and review the preview. The preview does not itself validate values.','Select Validate and import. Rejected imports record a failure; accepted imports append new rows and archive the original CSV.','Review the success count and import history; inspect Data Quality for missing values and unmatched IDs.','Use the stored dataset explorer and export button to download records.'] : p(x,'List Number')
p('Duplicates inside the uploaded CSV are rejected by configured dataset keys. Existing database identifiers are not silently updated because inserts use INSERT OR IGNORE. CSV validation checks required columns/values, numeric values, date parsing, coordinates, integer fields and operation count logic. Foreign key validation is currently diagnostic after import, not a blocking import gate.')

h('8. Analytics and formulas')
table(['Metric','Implemented calculation','Inputs and limitation'],[
('Total passengers','sum(passengers)','Ridership rows; means only the imported scope.'),('Trip count','unique trip_id when present; else sum(trips), else row count','Definition depends on source schema; fallback row count is not necessarily actual trips.'),('Route demand','sum(passengers) grouped by route_id','Requires route IDs and comparable coverage.'),('Daily/weekly/monthly','sum passengers by service date, week start or month start','Ridership page; filter changes aggregate.'),('Moving average','rolling mean: 7 daily points or 4 weekly/monthly buckets','Not a forecast; initial windows use available prior records.'),('Peak period','mean passengers grouped by time_period','Only useful when period labels are defined; observed schema lacks time_period, so it becomes Unspecified.'),('Weekday/weekend','mean passenger count per record by service-date day type','Record-level comparison, not necessarily day totals.'),('Revenue','sum(revenue); Overview formats as ₹','Currency is not stored in schema; displayed rupee symbol assumes INR and must be verified for imported data.'),('Route distance','source distance_km displayed and compared','Not derived; route records may be proposed.'),('Stop coverage','unique linked stop_id count per route','Counts documentation only, not geographic coverage.'),('Average occupancy','mean(capacity_utilisation) × 100 when field exists','Simulation only currently; imported fleet capacity is not joined to observed operations.'),('On-time performance','mean(on_time) × 100; observed derived rule delay ≤ 5 minutes','Threshold is an application rule, not an official standard.'),('Mean delay','mean departure delay in minutes','Derived from actual minus scheduled departure if not supplied.'),('Trip completion','count status == Completed','Operations page’s Completed KPI.'),('Vehicle utilisation','unique trip count per bus','Trip assignment count, not hours, kilometres or capacity use.'),('Completeness','missing cell count and duplicate whole rows','Data Quality summary; not a validated source coverage percentage.')])
p('Growth rates, citywide modal share, occupancy for observed records, network population coverage, service frequency adherence and revenue yield are not currently calculated. They require additional definitions and source fields; treat formulas for them as future work, not current outputs.')

h('9. Database and technical architecture')
p('SQLite stores observed data locally in data/ridership.sqlite. transport_core.initialise creates missing tables and adds compatible columns/indexes; it does not recreate the database. Pandas reads table contents for display. Streamlit reruns the script on interaction; Plotly Express charts are constructed from the currently selected DataFrame. simulation.py returns synthetic DataFrames without writing them to SQLite.')
table(['Table','Role'],[['routes','Route identifiers, names and planning/route attributes'],['stops','Stop details, route reference and sequence'],['fleet','Vehicle ID, route, capacity, type and status'],['ridership','Dated passenger records, optional trips/revenue and source file'],['operations','Dated route/bus scheduled and actual trip counts, delay and source file'],['dataset_imports','Dataset, file, time, received/added counts, status, hash and notes'],['data_sources','Source, publisher, URL, date, geography, period, units, method and limitations']])
h('9.1 Architecture diagram',2)
for x in ['User selects mode and page in Streamlit','Research mode → transport_core → SQLite observed tables','Simulation mode → simulation.py (seeded generation) → in-memory DataFrames','Pandas filters/aggregates → Plotly charts, metrics and tables','Data Centre → CSV validation → append-only imports + import history + archived source file'] : p(x,'List Bullet')
h('9.2 Data flow',2); p('CSV or stored reference → schema and value checks → append-only SQLite write → duplicate/import logging → page-specific filter → aggregation → Plotly/table/export. Simulation follows a separate path: fixed-seed generator → in-memory frames → the same analysis pages; no SQLite import step occurs.')
h('9.3 Backup and recovery',2); p('Create database backup to copy a consistent SQLite snapshot into data/backups or download it. Recovery accepts a SQLite file only after integrity_check, requires the exact confirmation word RESTORE, and retains a backup of the current database before copying the candidate. Keep backups in a safe location and do not replace the only database copy.')

h('10. Research sources')
table(['Source and publisher','URL / date','Use and limits'],[
('Comprehensive Mobility Plan for Bareilly, MoHUA / UMTC','https://mohua.gov.in/upload/uploadfiles/files/Final-CMPreport-for-Bareilly.pdf · 2023','Planning routes, lengths and service proposals. Proposed design does not prove current operations or observed ridership.'),('Forecasting Urban Bus Demand in Bareilly, CEEW','https://www.ceew.in/sites/default/files/factsheet-forecasting-urban-bus-demand-web.pdf · factsheet publication recorded in source audit','Scenario model for demand and fleet planning. Modelled values are not passenger observations.'),('SUGAM Yatra MIS & Reporting, UPSRTC','https://sugamyatra.up.in/MIS-reporting.html · project audit access date 2026-10-31','Describes possible MIS capabilities and fields; not a public Bareilly data download.'),('Buses: Bareilly Smart City, Open Government Data Platform India','https://up.data.gov.in/catalog/buses-bareilly-smart-city · checked 2026-10-31','Catalogue lead; project audit found no usable dataset (“No Result Found”).')])
p('The repository source_register.csv is the project register. Existing route reference means a route recorded in the local database and source material. Proposed route means a CMP planning proposal. Observed ridership means imported operational passenger records. Published aggregate evidence reports totals or scenarios with their own scope. Synthetic data is generated only for demonstration.')

h('11. Troubleshooting')
table(['Problem','Safe response'],[
('Python not recognised','Install Python from python.org and enable the Python launcher, then open a new terminal and try `py --version`.'),('Missing packages','Run `.venv\\Scripts\\python.exe -m pip install -r requirements.txt` from the project folder.'),('Activation blocked','Skip activation and invoke `.venv\\Scripts\\python.exe` directly; no system policy change is needed.'),('Streamlit not found','Run `python -m streamlit run app.py` or the venv executable form.'),('Port 8501 busy','Use `--server.port 8502` and open localhost:8502.'),('CSV rejected','Compare exact headers with the selected template; check required blanks, dates, numeric values, coordinates, integer fields and duplicate keys.'),('Unmatched route/bus','Add/import the correct reference row or correct the source ID. Data Quality warns but does not block all imports.'),('Empty charts','Check the selected mode, whether records exist, and route/date filters. Research tables currently contain no ridership/fleet/operations.'),('Database issue','Stop the app, copy the database and backups before any recovery. Use System & Method integrity check and only restore a verified SQLite backup.'),('App crashes','Read the terminal traceback; verify dependencies and CSV schema. Restart with the documented Streamlit command.')])

h('12. Project evaluation and future scope')
h('12.1 Current achievements',2); p('The project provides a multi-page dashboard; five observed import schemas; SQLite storage; import history; source registration; CSV exports; integrity check; backup and guarded restore; data-quality summaries; route/stop analysis; and a reproducible synthetic demonstration scenario.')
h('12.2 Current limitations',2); p('Observed ridership, fleet and operations tables are empty in the inspected project state. The imported schema for operations uses daily trip counts rather than scheduled/actual timestamped trip events. The user interface’s delay, on-time, completion and utilisation analysis aligns with the richer simulation fields and will not work on the narrower observed operations schema as currently written. Source metadata is registered separately from individual import records. Stop coordinates are missing for the documented reference stops.')
h('12.3 Future recommendations',2); bullets(['Obtain authorised Bareilly-specific passenger, schedule, fleet and stop extracts.','Extend observed schemas to store trip IDs, departure/arrival timestamps, operational status and capacity-use definitions.','Enforce route_id and bus_id relationships during import, with a clear resolution workflow.','Add source metadata at import time and preserve each dataset’s measurement unit and period.','Add verified geospatial layers only when coordinates and route geometries have documented sources.','Consider forecasting only after enough observed, consistent history exists; validate forecasts separately from observations.'])

h('13. Glossary and quick reference')
table(['Term','Meaning'],[['Ridership','Passengers recorded as using a transport service.'],['Route ID','Stable identifier used to connect route-related records.'],['Stop sequence','Order of stops along a documented route.'],['Headway','Time between successive services, usually minutes.'],['Frequency','Services per hour.'],['Primary key','Unique identifier for a table record.'],['Foreign key','Reference from a record to another table’s identifier.'],['Data provenance','Information about who produced data, when, how and with what limits.'],['Observed data','Records from documented real-world measurements or operations.'],['Modelled estimate','Value produced by assumptions and a model.'],['Synthetic data','Artificial data generated for demonstration or testing.'],['Moving average','Average over a rolling set of adjacent time buckets.'],['On-time threshold','Rule used to classify a departure as on time; current derived rule is delay ≤ 5 minutes.']])
h('One-page operating checklist',2); bullets(['Start the app from the project directory and open localhost:8501.','Read the selected mode; keep the simulation warning visible in demonstrations.','For imports, use the matching template and retain source documentation.','Check preview, validation feedback, import history and Data Quality.','Compare records only when periods, units and coverage match.','Back up the database before recovery or major changes.','Label proposals, published estimates and simulation accurately in presentations.'])

h('14. Conclusion')
p('Public Transport Ridership Analysis provides a practical foundation for transport data management and analytics for a Bareilly academic case study. Its observed-data mode is ready for verified imports, while the simulation mode demonstrates how linked ridership, route, stop, fleet and operations data can be explored. Results should be interpreted according to their evidence type, measurement period and completeness. Reliable local operational data is the main requirement for stronger conclusions.')
